from langgraph.types import interrupt, Command

def send_email(state):
    decision = interrupt({                    # pauses the graph and surfaces this payload
        "action": "send_email",
        "draft": state["draft"],
        "question": "Approve sending?",
    })
    if decision["approved"]:
        deliver(state["draft"])
        return {"status": "sent"}
    return {"status": "cancelled"}

